import json,pathlib
out={k:{} for k in ['ta','hi','ml','kn']}
def row(key,*values):
 for lang,val in zip(out,values):out[lang][key]=val
row('courseDesc.salesforce','Salesforce நிர்வாகம், Apex, LWC, பாதுகாப்பு, தானியக்கம் மற்றும் சோதனையைச் செயல்முறைத் திட்டங்கள் மூலம் கற்றிடுங்கள்.','व्यावहारिक प्रोजेक्ट के साथ Salesforce प्रशासन, Apex, LWC, सुरक्षा, ऑटोमेशन और टेस्टिंग सीखें।','പ്രായോഗിക പ്രോജക്റ്റുകളിലൂടെ Salesforce അഡ്മിനിസ്ട്രേഷൻ, Apex, LWC, സുരക്ഷ, ഓട്ടോമേഷൻ, ടെസ്റ്റിംഗ് എന്നിവ പഠിക്കൂ.','ಪ್ರಾಯೋಗಿಕ ಪ್ರಾಜೆಕ್ಟ್‌ಗಳ ಮೂಲಕ Salesforce ಆಡಳಿತ, Apex, LWC, ಭದ್ರತೆ, ಸ್ವಯಂಚಾಲನೆ ಮತ್ತು ಪರೀಕ್ಷೆ ಕಲಿಯಿರಿ.')
row('courseDesc.mern-stack','React முதல் APIs, தரவுத்தளங்கள், அங்கீகாரம் மற்றும் வெளியீடு வரை முழுமையான செயலிகளை உருவாக்குங்கள்.','React से शुरू करके APIs, डेटाबेस, ऑथेंटिकेशन और डिप्लॉयमेंट सहित पूरी ऐप बनाएँ।','React മുതൽ APIs, ഡാറ്റാബേസ്, ഓതന്റിക്കേഷൻ, വിന്യാസം വരെ സമ്പൂർണ ആപ്പുകൾ നിർമ്മിക്കൂ.','React ನಿಂದ APIs, ಡೇಟಾಬೇಸ್, ದೃಢೀಕರಣ ಮತ್ತು ನಿಯೋಜನೆಯವರೆಗೆ ಸಂಪೂರ್ಣ ಆಪ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಿ.')
row('courseDesc.ui-ux','பயனர் ஆய்விலிருந்து Figma வடிவமைப்பு, முன்மாதிரி மற்றும் போர்ட்ஃபோலியோ வரை முழுப் பயணத்தைக் கற்றிடுங்கள்.','यूज़र रिसर्च से Figma डिज़ाइन, प्रोटोटाइप और पोर्टफोलियो केस स्टडी तक पूरा सफर सीखें।','ഉപയോക്തൃ ഗവേഷണം മുതൽ Figma ഡിസൈൻ, പ്രോട്ടോടൈപ്പ്, പോർട്ട്ഫോളിയോ വരെ പഠിക്കൂ.','ಬಳಕೆದಾರ ಸಂಶೋಧನೆಯಿಂದ Figma ವಿನ್ಯಾಸ, ಮಾದರಿ ಮತ್ತು ಪೋರ್ಟ್‌ಫೋಲಿಯೋವರೆಗೆ ಕಲಿಯಿರಿ.')
row('courseDesc.python','நிரலாக்க அடிப்படைகள், தானியக்க வேலைகள் மற்றும் Python APIs உருவாக்குவதைக் கற்றிடுங்கள்.','प्रोग्रामिंग की मज़बूत बुनियाद बनाएँ, काम ऑटोमेट करें और उपयोगी Python APIs बनाएँ।','പ്രോഗ്രാമിംഗിന്റെ അടിസ്ഥാനം ഉറപ്പാക്കൂ, ജോലികൾ ഓട്ടോമേറ്റ് ചെയ്യൂ, Python APIs നിർമ്മിക്കൂ.','ಪ್ರೋಗ್ರಾಮಿಂಗ್ ಅಡಿಪಾಯ ಬಲಪಡಿಸಿ, ಕೆಲಸಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತಗೊಳಿಸಿ ಮತ್ತು Python APIs ನಿರ್ಮಿಸಿ.')
row('courseHeadline.salesforce','Salesforce தொழில்முறைப் பணிக்குத் தயாராகுங்கள்.','Salesforce में पेशेवर काम के लिए तैयार हों।','Salesforce പ്രൊഫഷണൽ ജോലിക്കായി തയ്യാറാകൂ.','Salesforce ವೃತ್ತಿಪರ ಕೆಲಸಕ್ಕೆ ಸಿದ್ಧರಾಗಿ.')
row('courseHeadline.mern-stack','நவீன முழுமையான வலைச் செயலிகளை உருவாக்குங்கள்.','आधुनिक वेब ऐप पूरी तरह बनाएँ।','സമ്പൂർണ ആധുനിക വെബ് ആപ്പുകൾ നിർമ്മിക്കൂ.','ಸಂಪೂರ್ಣ ಆಧುನಿಕ ವೆಬ್ ಆಪ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಿ.')
row('courseHeadline.ui-ux','மக்கள் விரும்பிப் பயன்படுத்தும் தயாரிப்புகளை வடிவமைக்கவும்.','ऐसे डिजिटल प्रोडक्ट डिज़ाइन करें जिन्हें लोग पसंद करें।','ആളുകൾ ഇഷ്ടപ്പെടുന്ന ഡിജിറ്റൽ ഉൽപ്പന്നങ്ങൾ രൂപകൽപ്പന ചെയ്യൂ.','ಜನರು ಇಷ್ಟಪಡುವ ಡಿಜಿಟಲ್ ಉತ್ಪನ್ನಗಳನ್ನು ವಿನ್ಯಾಸಗೊಳಿಸಿ.')
row('courseHeadline.python','செயல்முறை நிரலாக்கம் மூலம் Python கற்றிடுங்கள்.','व्यावहारिक प्रोग्रामिंग से Python सीखें।','പ്രായോഗിക പ്രോഗ്രാമിംഗിലൂടെ Python പഠിക്കൂ.','ಪ್ರಾಯೋಗಿಕ ಪ್ರೋಗ್ರಾಮಿಂಗ್ ಮೂಲಕ Python ಕಲಿಯಿರಿ.')
